package app.veyra;
import android.app.*;import android.content.*;import android.os.*;import androidx.media3.common.MediaItem;import androidx.media3.exoplayer.offline.*;import androidx.media3.datasource.cache.*;import app.veyra.data.*;import app.veyra.model.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public final class DownloadWorker extends Service {
 private static volatile String activeId;private volatile Downloader downloader;private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean cancelled;private long lastNotify;private String policyError="";
 static boolean active(){return activeId!=null;}static boolean isActive(String id){return id!=null&&id.equals(activeId);}
 static void start(Activity activity,String playback){start(activity,playback,"");}
 static void start(Activity activity,String playback,String poster){String blocked=DownloadPolicy.blocked(activity,0,"");if(!blocked.isEmpty()){android.widget.Toast.makeText(activity,blocked,android.widget.Toast.LENGTH_LONG).show();return;}if(active()){android.widget.Toast.makeText(activity,"Finish or cancel the current download first",android.widget.Toast.LENGTH_LONG).show();return;}Intent intent=new Intent(activity,DownloadWorker.class).putExtra("playback",playback).putExtra("poster",poster);if(Build.VERSION.SDK_INT>=26)activity.startForegroundService(intent);else activity.startService(intent);}
 private Notification notification(String title,int percent){Intent open=new Intent(this,DownloadsActivity.class);PendingIntent content=PendingIntent.getActivity(this,2,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);PendingIntent cancel=PendingIntent.getService(this,3,new Intent(this,DownloadWorker.class).setAction("cancel"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"downloads"):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.stat_sys_download).setContentTitle(getSharedPreferences("settings",0).getBoolean("privateDownloadNotices",false)?"Velixio download":title).setContentText(percent<0?"Preparing offline copy":percent+"% downloaded").setProgress(100,Math.max(0,percent),percent<0).setContentIntent(content).setOngoing(true).addAction(android.R.drawable.ic_menu_close_clear_cancel,"Cancel",cancel).build();}
 @Override public int onStartCommand(Intent intent,int flags,int startId){if(intent!=null&&"cancel".equals(intent.getAction())){cancelled=true;if(downloader!=null)downloader.cancel();return START_NOT_STICKY;}if(active())return START_NOT_STICKY;activeId=UUID.randomUUID().toString();if(Build.VERSION.SDK_INT>=26)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).createNotificationChannel(new NotificationChannel("downloads","Offline downloads",NotificationManager.IMPORTANCE_LOW));startForeground(91,notification("Velixio download",-1));String id=activeId;String json=intent==null?null:intent.getStringExtra("playback");String poster=intent==null?"":intent.getStringExtra("poster");worker.execute(()->download(id,json,poster));return START_NOT_STICKY;}
 private void download(String id,String json,String poster){JSONObject record=new JSONObject();try{PlaybackRequest request=PlaybackJson.parseInternal(json);StreamSource source=request.sources.get(0);record.put("title",request.title).put("url",source.url).put("mime",source.mimeType).put("created",System.currentTimeMillis()).put("state","downloading").put("percent",0);PosterLoader.saveAvailableArtwork(this,id,poster);OfflineStore.save(this,id,record);CacheDataSource.Factory factory=new CacheDataSource.Factory().setCache(OfflineStore.cache(this,id)).setUpstreamDataSourceFactory(StreamHttp.factory(source));DownloadRequest download=new DownloadRequest.Builder(id,android.net.Uri.parse(source.url)).setMimeType(source.mimeType).build();downloader=new DefaultDownloaderFactory(factory).createDownloader(download);downloader.download((length,bytes,percent)->{policyError=DownloadPolicy.blocked(this,bytes,id);if(!policyError.isEmpty()||cancelled||getFilesDir().getUsableSpace()<256L*1024*1024||bytes>8L*1024*1024*1024){cancelled=true;downloader.cancel();return;}long now=System.currentTimeMillis();if(now-lastNotify>1500){lastNotify=now;try{record.put("percent",Math.max(0,(int)percent));record.put("bytes",bytes);OfflineStore.save(this,id,record);if(Build.VERSION.SDK_INT<33||checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)==android.content.pm.PackageManager.PERMISSION_GRANTED)((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(91,notification(request.title,(int)percent));}catch(Exception ignored){}}});if(cancelled)throw new InterruptedException();record.put("bytes",OfflineStore.cache(this,id).getCacheSpace());record.put("state","complete").put("percent",100);OfflineStore.save(this,id,record);
 }catch(Exception e){try{androidx.media3.datasource.cache.SimpleCache partial=OfflineStore.cache(this,id);for(String key:new java.util.HashSet<>(partial.getKeys()))partial.removeResource(key);record.put("bytes",0);}catch(Exception ignored){}try{record.put("title",record.optString("title","Download")).put("state",cancelled?"cancelled":"failed").put("message",!policyError.isEmpty()?policyError:cancelled?"Cancelled or storage limit reached":"This stream could not be saved. Open the title online and try again.");OfflineStore.save(this,id,record);}catch(Exception ignored){}}finally{activeId=null;downloader=null;stopForeground(true);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(91);stopSelf();}}
 @Override public void onTimeout(int startId,int fgsType){cancelled=true;if(downloader!=null)downloader.cancel();stopSelf();}
 @Override public void onDestroy(){cancelled=true;if(downloader!=null)downloader.cancel();worker.shutdownNow();activeId=null;((VeyraApplication)getApplication()).downloadFinished();super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
